      {"DAG5", "UNIT_MASTER_CH_M024_HI_SLD_C_DAG", "BATTLE_UNITPARAM_CH_M024_SLD_C_DAG", 11, 4, CHAR_DIR_EAST, 0},
      {"RID1", "UNIT_MASTER_CH_M021_SLD_C_RID", "BATTLE_UNITPARAM_CH_M022_SLD_C_RID_RANK2", 2, 2, CHAR_DIR_EAST, 0},
